-- 验证父级SKU已创建
SELECT * FROM system_wms_yicang.hpoms_product_combo WHERE combo_sku = 'PARENT-SKU-001';
-- 验证子SKU绑定关系
SELECT * FROM system_wms_yicang.hpoms_product_combo_skus WHERE combo_id = (SELECT id FROM system_wms_yicang.hpoms_product_combo WHERE combo_sku = 'PARENT-SKU-001');
-- 验证业务日志
SELECT * FROM system_wms_yicang.hpoms_business_log ORDER BY create_time DESC LIMIT 1;

-- 验证父级SKU未被创建
SELECT COUNT(*) FROM system_wms_yicang.hpoms_product_combo WHERE combo_sku = 'PARENT-SKU-002';
-- 期望结果：0
-- 验证失败日志已记录
SELECT * FROM system_wms_yicang.hpoms_business_log WHERE operation_result = 'FAIL' ORDER BY create_time DESC LIMIT 1;

-- 验证父级SKU未重复新增
SELECT COUNT(*) FROM system_wms_yicang.hpoms_product_combo WHERE combo_sku = 'PARENT-EXIST-001';
-- 期望结果：1（仅原有一条）
